def make_empty_chest():
    empty = pd.DataFrame(columns=['timestamp', 'accel_x', 'accel_y', 'accel_z']).set_index('timestamp')
    empty.index = unix_to_timestamps(empty.index)
    return empty


def make_empty_wrist():
    empty = pd.DataFrame(columns=['timestamp', 'x', 'y', 'z']).set_index('timestamp')
    empty.index = unix_to_timestamps(empty.index)
    return empty


class AccelLoadError(Exception):

    def __init__(self, field, *args, params=None, parent=None, **kwargs):
        self.field = field
        self.params = params
        self.cause = parent
        super(AccelLoadError, self).__init__(*args, **kwargs)


class AccelSpec(ABC):

    group_name = "Accelerometer"
    dataset_name = "AccelStream"
    time_name = "Timestamps"


class AccelReader(AccelSpec, DataReader):
    """
    Wrapper class for reading accelerometer data from the HDF5 storage
    """


class AccelWriter(AccelSpec, DataWriter):
    """
    Wrapper class for converting accelerometer data into the HDF5 format
    """

    point_shape = (2, 2, 3)
    chunk_spec = (None,)
    dim_names = ['Time', 'Location', 'Side', 'Axis']
    dim_labels = [
        None,
        ['Wrist', 'Chest'],
        ['Left', 'Right'],
        ['x', 'y', 'z']
    ]

    def __init__(self, location):
        self.left_chest = None
        self.right_chest = None

        self.watch_data = None
        self.metadata = None

        self.known_offsets = {}

        super(AccelWriter, self).__init__(location)

    @classmethod
    def from_sources(cls, output, wrist_spec, rcs_left, rcs_right):

        accel = cls(output)

        accel.left_chest = undupe_time(
            pd.read_csv(os.path.join(rcs_left, settings.RCS_ACCEL_FILENAME), index_col=['timestamp'], header=0))
        accel.right_chest = undupe_time(
            pd.read_csv(os.path.join(rcs_right, settings.RCS_ACCEL_FILENAME), index_col=['timestamp'], header=0))

        # Log in to the rune API
        client = get_client()
        accel.watch_data = get_bilateral_watch_data(client, 'accel', **wrist_spec)

        accel.metadata = {
            'load datetime': datetime.datetime.now().timestamp()
        }
        return accel

    @classmethod
    def from_rune_only(cls, output, wrist_spec, known_offsets=None):
        accel = cls(output)

        # Log in to the rune API and pull the required apple watch data
        client = get_client()
        accel.watch_data = get_bilateral_watch_data(client, 'accel', **wrist_spec)

        # Need to make some empty RC+S accelerometer data
        accel.left_chest = make_empty_chest()
        accel.right_chest = make_empty_chest()

        accel.known_offsets = {} if known_offsets is None else known_offsets

        accel.metadata = {
            'load datetime': datetime.datetime.now().timestamp()
        }
        return accel

    @classmethod
    def from_neural_src(cls, output, left_source=None, right_source=None, patient_id=None):
        """
        Load accelerometry based on a time interval from RC+S data file names
        """
        edges = []
        if left_source is not None:
            edges.extend(file_start_end(left_source))
        if right_source is not None:
            edges.extend(file_start_end(right_source))

        if edges:
            t_range = min(edges), max(edges)
        else:
            raise DataLoadError('Could not load time edges from file names!')

        load_spec = {
            'time_range': t_range,
            'patient_id': patient_id,
            'left_watch_id': RUNE_WATCH_IDS[patient_id]['left'],
            'right_watch_id':  RUNE_WATCH_IDS[patient_id]['right']
        }
        return cls.from_sources(output, load_spec, left_source, right_source)

    @classmethod
    def from_stack(cls, writers, patient=None):

        inter_writes = []
        for i, w in enumerate(writers):
            if i + 1 >= len(writers):
                break
            else:
                prev_w, next_w = w, writers[i+1]
                aligns = {
                    k: np.mean([v1, v2]) for (k, v1), (k, v2) in
                    zip(prev_w.alignments.items(), next_w.alignments.items())
                }
                load_spec = {
                    'time_range': timestamp_to_unix([prev_w._timestamps[-1], next_w._timestamps[0]]),
                    'patient_id': patient,
                    'left_watch_id': RUNE_WATCH_IDS[patient]['left'],
                    'right_watch_id': RUNE_WATCH_IDS[patient]['right']
                }
                inter_w = cls.from_rune_only(prev_w.file_location, load_spec, known_offsets=aligns)
                try:
                    inter_w.load()
                except AccelLoadError:
                    inter_w = None  # Need to keep a dummy to ensure order is correct when combining
                inter_writes.append(inter_w)

        combined = [None]*(len(writers)+len(inter_writes))
        combined[::2] = writers
        combined[1::2] = inter_writes
        combined = [c for c in combined if c is not None]  # Remove any dummy writers
        stacked = super(AccelWriter, cls).from_stack(combined)
        return stacked

    def set_alignments(self, alignments):
        for k, v in alignments.items():
            if 'offset' in k:
                side = k.split(' ')[0]
                self.known_offsets[side] = v
            self.metadata[k] = v

    @property
    def alignments(self):
        """
        Return the alignment offsets computed using cross-correlation

        :return: dictionary of offsets
            - "left_side": offset applied to the left chest time to bring it in line with left wrist time
            - "right_side": offset applied to the right chest time to bring it in line with right wrist time
            - "cross_chest": offset applied to all the left side time to bring it in line with right side time
        """
        return {
            'left_side': pd.Timedelta(self.metadata['left_side offset']),
            'right_side': pd.Timedelta(self.metadata['right_side offset']),
            'cross_side': pd.Timedelta(self.metadata['cross_side offset'])
        }

    def align(self, to_align, base_time, label=None, apply=True, scale=1):
        """
        Align the data from one time series to match that of another time series

        Currently, this function uses a manual alignment method if self.known_timestamps does not already contain a
            matching time offset.

        :param to_align: pd.DataFrame with a DateTimeIndex, which contains 3-axis accelerometer data to align
        :param base_time: same format as to_align, but this it considered to be the 'true' wall clock time
        :param label: name/label of this alignment, used to look up a known offset and to save the estimate offset
        :param apply: boolean, whether to apply the estimated offset to to_align before returning
        :param scale: relative y-scale of the data in the two dataframes. used only for plotting
        :returns: pd.Dataframe, the data to align, with the offset applied is apply is True
        """
        if self.known_offsets and label in self.known_offsets.keys():
            try:
                offset = pd.Timedelta(seconds=self.known_offsets[label])
            except TypeError:
                offset = self.known_offsets[label]
        else:
            print(f'No alignments for {label} in {os.path.split(self.file_location)[-1]}')
            offsets = manual_align(base_time, scale=scale, second=to_align)
            offset = offsets['second']
            self.known_offsets[label] = offset
            warnings = [warning for warning in offsets['warnings'].keys()]
            self.metadata[f'{label} alignment warnings'] = warnings
            self.metadata['alignment method'] = 'manual'
        if apply:
            to_align.index += offset

        self.metadata[f'{label} offset'] = f'{round(offset.total_seconds(), 2)} seconds'

        return to_align

    def scipy_resample(self):
        pass

    @staticmethod
    def pick_chest_freq(chest_data):
        raw_freq = get_sample_freq(chest_data, discard_outliers=(0, 0.05), use_mean=True)
        try:
            true_freq = pick_sample_freq(raw_freq, settings.POSSIBLE_CHEST_SFS)
        except ValueError:
            raw_freq = get_sample_freq(chest_data, discard_outliers=(0, 0.05), use_mean=False)
            true_freq = pick_sample_freq(raw_freq, settings.POSSIBLE_CHEST_SFS)
        return true_freq

    @staticmethod
    def pick_watch_freq(watch_data):
        raw_freq = get_sample_freq(watch_data, discard_outliers=(0., 0.1), use_mean=False)
        return pick_sample_freq(raw_freq, settings.POSSIBLE_WATCH_SFS, error_threshold=None)

    def align_side(self, watch_data, chest_data, side):
        """Align the RC+S and wristwatch accelerometer data from one side of the body"""

        have_watch = len(watch_data) > 2
        have_chest = len(chest_data) > 2

        # Need to have at least two then there's no resampling to do, and we don't really have any alignment to do
        if not have_chest and not have_watch:
            time = pd.DatetimeIndex([]).tz_localize('US/Pacific')
            wrist = chest = make_empty_chest().values

        else:
            # If we have chest data, then we can use this to set the time limits
            if have_chest:
                target_index = unix_to_timestamps(chest_data.index)
                chest_data.index = target_index
                chest_data /= 100  # Change chest data from centiG to G
                target_freq = self.pick_chest_freq(chest_data)

            # If we do not have chest data, then set time limits based on watch data, and use the
            # default chest sampling frequency to generate our target index
            else:
                target_freq = settings.DEFAULT_CHEST_SF
                lims = unix_to_timestamps([watch_data.index[0], watch_data.index[-1]], units='s')
                target_index = pd.date_range(start=lims[0], end=lims[1], freq=f'{round(1/target_freq , 4)}S')
                chest_data = chest_data.reindex(target_index)

            # Resample the watch data up to the chest data sampling rate
            if have_watch:
                watch_data.index = unix_to_timestamps(watch_data.index, units='s')
                watch_freq = self.pick_watch_freq(watch_data)
                if watch_freq == target_freq:
                    watch = watch_data
                else:
                    watch = pandas_resample(
                        watch_data, watch_freq, target_freq, interp_method=settings.WATCH_RESAMPLE_METHOD
                    )
                # Clean any leading NaN datapoints. These are not fillable, and can screw processing downstream
                while np.isnan(watch.iloc[0, 1]):
                    watch = watch.iloc[1:, :]

            else:
                watch = watch_data.reindex(target_index)

            # Align in time, onto the same set of timestamps, and stack together
            aligned_chest = self.align(chest_data, watch, label=side, scale=1)

            time, chest, wrist = align_timestamps(aligned_chest, watch, sample_freq=target_freq)

        side_data = np.stack([wrist, chest], axis=1)
        return time, side_data

    @staticmethod
    def make_side_df(side_time, side_data):
        """Prepare a resample-ready dataframe of all side data"""
        squash, shape = array_squash(side_data)
        side = pd.DataFrame.from_records(squash, index=side_time)
        return side, shape

    def cross_side_align(self, l_time, l_data, r_time, r_data):
        """
        Calculate a new left side time so that the two sides are aligned in real time

        Handle the situations in which the data from either the left or right side is entirely empty.

        """

        have_left = len(l_data) > 1
        have_right = len(r_data) > 1

        if have_left and have_right:
            # We have both sides! We can try to meaningfully align the data
            l_chest = pd.DataFrame.from_records(l_data[:, 1], index=l_time)
            r_chest = pd.DataFrame.from_records(r_data[:, 1], index=r_time)

            self.align(l_chest, r_chest, 'cross_side', scale=1, apply=False)
            new_l_time = l_time + self.alignments['cross_side']

        else:
            self.metadata['cross_side offset'] = f'0 seconds'
            if not have_left and have_right:
                # We only have right side data, make the left side data match in shape and time, filled with NaN
                l_data = np.empty(r_data.shape)
                l_data[:] = np.NaN
                new_l_time = r_time
            elif have_left and not have_right:
                # We only have left side data, make the right side data match in shape and time, filled with NaN
                r_data = np.empty(l_data.shape)
                r_data[:] = np.NaN
                r_time = new_l_time = l_time
            else:
                # We have neither left nor right. There's no way to interpret timestamps from the data available here
                raise AccelLoadError('No accel data to load!')

        left_side, l_shape = self.make_side_df(new_l_time, l_data)
        right_side, r_shape = self.make_side_df(r_time, r_data)

        return left_side, l_shape, right_side, r_shape

    def prep_data(self):

        l_time, l_data = self.align_side(self.watch_data[0], self.left_chest, 'left_side')
        r_time, r_data = self.align_side(self.watch_data[1], self.right_chest, 'right_side')

        left_side, l_shape, right_side, r_shape = self.cross_side_align(l_time, l_data, r_time, r_data)

        time, left, right = align_timestamps(left_side, right_side)
        all_accel = np.stack([
            array_unsquash(left.values, l_shape),
            array_unsquash(right.values, r_shape)],
            axis=2)

        return time, all_accel

    def prep_attributes(self):
        base_attr = super(AccelWriter, self).prep_attributes()

        try:
            original_watch_freq = get_sample_freq(self.watch_data[0])
        except IndexError:
            original_watch_freq = None
        try:
            original_chest_freq = get_sample_freq(self.left_chest)
        except IndexError:
            original_chest_freq = None

        self.metadata.update({
            'watch resample method': settings.WATCH_RESAMPLE_METHOD,
            'original watch freq': original_watch_freq,
            'original chest freq': original_chest_freq
        })
        clean_meta = {k: repr(v) for k, v in self.metadata.items()}
        base_attr.update(clean_meta)

        return base_attr


